import { useSelector } from "react-redux";
import { userSelector } from "../../store/selectors/userSelectors";

import "./UserData.css";

const UserData = () => {
  const users = useSelector(userSelector);
  return <div>
    {users.map((elm)=>
    <div key={elm.id}>
        <p></p>
    </div>
    )}
  </div>;
};

export default UserData;
